#include<bits/stdc++.h>
using namespace std;
int main(int ac,char**av){if(ac<7)return 1;int n=atoi(av[1]);long long steps=atoll(av[2]);mt19937_64 rng(stoull(av[3]));string out=av[4];double tmax=atof(av[5]);int dw=atoi(av[6]);if(n>63)return 2;vector<uint64_t>adj(n);vector<pair<int,int>>edges;
if(ac>7&&string(av[7])!="-"){ifstream f(av[7]);for(int u=0;u<n;u++)for(int t=0;t<4;t++){int v;f>>v;adj[u]|=1ull<<v;}}else{for(int u=0;u<n;u++)for(int d:{1,2}){int v=(u+d)%n;adj[u]|=1ull<<v;adj[v]|=1ull<<u;}}
for(int u=0;u<n;u++){if(__builtin_popcountll(adj[u])!=4||((adj[u]>>u)&1)){cerr<<"invalid warm\n";return 2;}for(int v=u+1;v<n;v++)if(adj[u]>>v&1)edges.push_back({u,v});}if(edges.size()!=2*n)return 3;
int raw=0,diag=0;auto score=[&](){uint64_t r2[64]={};for(int u=0;u<n;u++){uint64_t m=adj[u];while(m){int v=__builtin_ctzll(m);m&=m-1;r2[u]|=adj[v];}}raw=diag=0;for(int u=0;u<n;u++){uint64_t r3=0,m=adj[u];while(m){int v=__builtin_ctzll(m);m&=m-1;r3|=r2[v];}raw+=n-__builtin_popcountll(r3);diag+=!(r3>>u&1);}return raw+dw*diag;};
int val=score(),best=val;auto bestAdj=adj;auto bestEdges=edges;auto start=chrono::steady_clock::now();long long bestIt=0;auto save=[&](long long it){bestAdj=adj;bestEdges=edges;bestIt=it;ofstream f(out+".rawadj");for(int u=0;u<n;u++){uint64_t m=adj[u];bool first=true;while(m){int v=__builtin_ctzll(m);m&=m-1;if(!first)f<<' ';f<<v;first=false;}f<<'\n';}ofstream j(out+".json");j<<"{\"n\":"<<n<<",\"degree\":4,\"score\":"<<best<<",\"missing_odd3_pairs\":"<<raw<<",\"diagonal_missing\":"<<diag<<",\"seed\":"<<av[3]<<",\"iteration\":"<<it<<",\"seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}";cerr<<"best "<<best<<" raw "<<raw<<" diag "<<diag<<" it "<<it<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';};save(0);
for(long long it=1;it<=steps;it++){int i=rng()%edges.size(),j=rng()%edges.size();if(i==j)continue;auto [a,b]=edges[i];auto[c,d]=edges[j];if(rng()%2)swap(c,d);if(a==c||a==d||b==c||b==d)continue;if((adj[a]>>d&1)||(adj[c]>>b&1))continue;
adj[a]^=(1ull<<b)|(1ull<<d);adj[b]^=(1ull<<a)|(1ull<<c);adj[c]^=(1ull<<d)|(1ull<<b);adj[d]^=(1ull<<c)|(1ull<<a);int nv=score();double T=.04+tmax*pow(.002,(it%300000)/300000.);if(nv<=val||uniform_real_distribution<double>(0,1)(rng)<exp((val-nv)/T)){val=nv;edges[i]={a,d};edges[j]={c,b};if(val<best){best=val;save(it);if(!raw)break;}}else{adj[a]^=(1ull<<b)|(1ull<<d);adj[b]^=(1ull<<a)|(1ull<<c);adj[c]^=(1ull<<d)|(1ull<<b);adj[d]^=(1ull<<c)|(1ull<<a);}
if(it%300000==0&&rng()%2){adj=bestAdj;edges=bestEdges;val=best;}}
cerr<<"FINAL "<<best<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}
